import {useAuthorScope} from './StoreContext';
import {useEffect} from 'react';
import type {Entity,ProjectData,ProjectSnapshot} from '../domain/types';
import {newId} from '../domain/model';
import {PagedSelect} from './PagedSelect';
import {ListPager,useListWindow} from './ListWindow';
import {useAuthorField,useAuthorInput,authorField,flushAuthorDraft,acknowledgeAuthorDraft,AuthorDraftNotice} from './authorOperation';
/** Approval belongs to a particular old edition and public policy; it never borrows the current prose. */
export function ExportCitationTools({project,profileId,pins,onSave}:{project:ProjectData;profileId:string;pins:readonly ProjectSnapshot[];onSave:(entity:Entity)=>Promise<Entity>}){
 const key=useAuthorScope(`export-citations:${project.projectId}`),[version,setVersion]=useAuthorInput(key,'version','',project.projectId,project.revision),[childId,setChild]=useAuthorInput(key,'profile','',project.projectId,project.revision),[busy,setBusy]=useAuthorField(key,'busy',false),[error,setError]=useAuthorField(key,'error',''),[saved,setSaved]=useAuthorField<string|null>(key,'saved',null);
 const parent=project.entities.find((entity):entity is Entity<'projection_profile'>=>entity.id===profileId&&entity.kind==='projection_profile'&&!entity.deletedAt),pin=pins.find(pin=>pin.id===version),children=[...(pin?.content.entities??[]).filter(entity=>entity.kind==='projection_profile'&&entity.status==='confirmed'&&!entity.deletedAt),...project.entities.filter(entity=>entity.kind==='projection_profile'&&entity.status==='confirmed'&&!entity.deletedAt&&entity.data.sourceVersionId===version&&!pin?.content.entities.some(old=>old.id===entity.id))].filter(entity=>entity.id!==parent?.id);
 const rows=useListWindow({items:(parent?.data.citedVersions??[]).map(item=>({...item,id:item.sourceVersionId})),scope:`${key}:${profileId}:list`});
 useEffect(()=>{if(saved&&parent&&BigInt(project.revision)>=BigInt(saved)){setSaved(null);setBusy(false);}},[project.revision,parent,saved]);
 async function change(remove?:string){if(!parent||authorField<boolean>(key,'busy'))return;setBusy(true);const captured=structuredClone(parent),selectedPin=version,selectedChild=childId;try{await flushAuthorDraft(key);if(!remove&&(!pins.some(pin=>pin.id===selectedPin)||!children.some(child=>child.id===selectedChild)))throw Error('引用する固定版と、その版の確認済み公開範囲を選んでください。');const existing=captured.data.citedVersions??[];const declarations=remove?existing.filter(item=>item.sourceVersionId!==remove):[...existing.filter(item=>item.sourceVersionId!==selectedPin),{sourceVersionId:selectedPin,profileId:selectedChild,publicVersionId:existing.find(item=>item.sourceVersionId===selectedPin)?.publicVersionId??newId()}];const result=await onSave({...captured,data:{...captured.data,citedVersions:declarations}});acknowledgeAuthorDraft(key,result.revision);setSaved(result.revision);setError('');}catch(cause){setError((cause as Error).message);setBusy(false);}}
 if(!parent)return null;
 return <section className="settings-card"><h3>引用する固定版の公開範囲</h3><p className="field-hint">旧本文・文字位置・媒体の元設定を含めるときは、その版で公開文を確認した範囲を指定してください。</p><AuthorDraftNotice scope={key} revision={project.revision}/><fieldset disabled={busy}><PagedSelect label="公開出力へ引用する固定版" scope={`${key}:versions`} items={pins.map(pin=>({id:pin.id,label:pin.versionLabel}))} value={version} onChange={id=>{setVersion(id);setChild('');}}/><PagedSelect label="引用版の確認済み公開範囲" scope={`${key}:profiles`} items={children.map(entity=>({id:entity.id,label:entity.name}))} value={childId} onChange={setChild}/><button disabled={!version||!childId} onClick={()=>void change()}>この固定版の公開引用を保存</button>{rows.items.map(item=><p key={item.id}>固定版 {pins.find(pin=>pin.id===item.sourceVersionId)?.versionLabel??item.sourceVersionId} · 公開範囲 {project.entities.find(entity=>entity.id===item.profileId)?.name??item.profileId}<button onClick={()=>void change(item.sourceVersionId)}>引用承認を外す</button></p>)}</fieldset><ListPager {...rows} label="公開引用"/>{error&&<p role="alert">{error}</p>}</section>;
}
